import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
export default { distDir: '.next-health', turbopack: { root } };

const products = [{ id: 'lamp', name: 'Desk Lamp', priceCents: 4950 }];

export default function StorefrontPage() {
  throw new Error('TODO render storefront');
}

import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { readFile, rm, stat } from 'node:fs/promises';
import test from 'node:test';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const run = promisify(execFile);
const root = fileURLToPath(new URL('..', import.meta.url));
const output = fileURLToPath(new URL('../.next-health', import.meta.url));

test('Next App Router completes a production build', { timeout: 240000 }, async () => {
  try {
    await run(process.execPath, ['node_modules/next/dist/bin/next', 'build'], { cwd: root, env: { ...process.env, CI: '1', NEXT_TELEMETRY_DISABLED: '1' }, maxBuffer: 4 * 1024 * 1024, timeout: 220000 });
    assert.equal((await stat(new URL('../.next-health/BUILD_ID', import.meta.url))).isFile(), true);
    const source = await readFile(new URL('../app/page.jsx', import.meta.url), 'utf8');
    assert.doesNotMatch(source, /TODO/);
    assert.match(source, /data-product-id/);
    assert.match(source, /Desk Lamp/);
  } finally {
    await rm(output, { recursive: true, force: true });
  }
});
